import { BudgetExceeded, say, step } from '../context.ts';
import { peopleAt } from '../crust.ts';
import { env } from '../env.ts';
import { json } from '../llm.ts';
import { emit } from '../store.ts';
import type { Check, Deliverable, Item, Job } from '../types.ts';
import { FUNCTIONS, looksLikeDomain, personOf, personOnWeb, resolveCompany, SENIOR_LEVELS, seniority, toCsv, writeAudited } from './shared.ts';

/**
 * People map: who to talk to at one company for one goal. The Lead works out which functions own
 * the decision, Records finds the people in those seats now, Field confirms each one on the open web.
 */

interface Intake {
  name: string;
  domain: string | null;
  goal: string;
  groups: { role: string; titles: string[]; function: string | null; why: string }[];
}

interface Candidate {
  name: string;
  title: string;
  since: string | null;
  profileUrl: string | null;
  seniority: string | null;
  group: number;
  rank: number;
}

const MAX = 8;

export async function runPeopleMap(job: Job): Promise<Deliverable> {
  const intake = await step(job, 'lead', 'intake', () =>
    json<Intake>({
      system: `You are the Lead at a research agency. A client wants to know who to talk to at one company for a specific goal. Extract the company (and its domain if given, else null) and work out 2-4 groups of people who matter for that goal: who signs off, who uses or owns the problem, who could block it. For each group give a short role label, 2-4 job-title forms as they appear in titles (e.g. "CHRO", "Head of People", "VP Human Resources"), the closest function from this list or null: ${FUNCTIONS.join(', ')}, and one sentence on why that group matters for the goal.`,
      user: `Client brief: ${job.brief}\nForm fields: ${JSON.stringify(job.input)}\n\nReturn {"name": string, "domain": string|null, "goal": string, "groups": [{"role", "titles": string[], "function": string|null, "why"}]}`,
      check: (v) => (!v?.name ? 'missing name' : !Array.isArray(v.groups) || !v.groups.length ? 'groups must be a non-empty array' : v.groups.some((g: any) => !Array.isArray(g.titles) || !g.titles.length) ? 'every group needs titles' : null),
    }),
  );
  intake.groups = intake.groups.slice(0, 4).map((g) => ({ ...g, function: FUNCTIONS.includes(g.function ?? '') ? g.function : null }));
  if (!job.plan) {
    job.plan = intake;
    say(`Work order: who to talk to at ${intake.name} for ${intake.goal}. Looking for ${intake.groups.map((g) => g.role).join(', ')}`, 'step');
  }

  const company = await step(job, 'lead', 'resolve', () => {
    const raw = String(job.input.company ?? '');
    return resolveCompany(intake.name, intake.domain ?? (looksLikeDomain(raw) ? raw : null), job.brief);
  });
  const name = company.name || intake.name;

  // Records: one search per group, by title or by function at a senior level.
  const pool = await step(job, 'records', 'people', async () => {
    const found: Candidate[] = [];
    for (const [gi, g] of intake.groups.entries()) {
      say(`Searching the people database at ${company.domain} for ${g.role}`, 'tool');
      const r = await peopleAt({ domain: company.domain, titles: g.titles, functions: g.function ? [g.function] : undefined, seniority: SENIOR_LEVELS, limit: 6 }).catch((e) => {
        if (e instanceof BudgetExceeded) throw e;
        say(`people search for ${g.role} failed (${e.message}); moving on`, 'recover');
        return { profiles: [] };
      });
      for (const p of (r.profiles ?? []).map(personOf)) {
        if (!p.name || found.some((f) => f.name.toLowerCase() === p.name.toLowerCase())) continue;
        found.push({ name: p.name, title: p.title, since: p.since, profileUrl: p.profileUrl, seniority: p.seniority, group: gi, rank: seniority(p.title, p.seniority) });
      }
    }
    // Most senior first, but take turns between groups so one function can't fill the map.
    const byGroup = intake.groups.map((_, gi) => found.filter((f) => f.group === gi).sort((a, b) => a.rank - b.rank));
    const order: Candidate[] = [];
    for (let round = 0; order.length < found.length; round++) for (const g of byGroup) if (g[round]) order.push(g[round]);
    say(`Records found ${found.length} people across ${intake.groups.length} groups`);
    return order.slice(0, MAX + 2);
  });
  if (!pool.length) throw new Error(`no current staff found at ${company.domain} for ${intake.groups.map((g) => g.role).join(', ')}`);

  // Field: each person on the open web. One search each, one step each, so a crash resumes mid-list.
  const items: (Item & { group: number })[] = [];
  let partial = false;
  try {
    for (const p of pool) {
      if (items.filter((i) => i.status === 'verified').length >= MAX) break;
      const item = await step(job, 'field', `confirm:${p.name}`, async () => {
        say(`Checking ${p.name} (${p.title}) on the open web`, 'tool');
        const web = await personOnWeb(p.name, name);
        const checks: Check[] = [
          { name: 'in the people database', ok: true, note: `${p.title}${p.since ? `, since ${String(p.since).slice(0, 7)}` : ''}`, source: p.profileUrl ?? 'crustdata' },
          {
            name: 'on the open web',
            ok: web.mentions.length > 0 && !web.left,
            note: web.left ? `web says they left: "${web.left.snippet.slice(0, 140)}"` : web.mentions.length ? `${web.mentions.length} page${web.mentions.length > 1 ? 's' : ''} link them to ${name}` : 'database only; no web page links them to the company',
            source: (web.left ?? web.mentions[0])?.url,
          },
        ];
        return {
          title: p.name,
          subtitle: p.title,
          link: p.profileUrl ?? undefined,
          status: web.left ? 'dropped' : 'verified',
          dropReason: web.left ? `the web says ${p.name} left ${name}` : undefined,
          checks,
          fields: { role: intake.groups[p.group].role, title: p.title, since: p.since ? String(p.since).slice(0, 10) : '', webConfirmed: String(web.mentions.length > 0 && !web.left) },
          group: p.group,
        } as Item & { group: number };
      }, { retries: 1 });
      items.push(item);
      emit(job, { agent: 'verifier', kind: 'check', text: item.status === 'verified' ? `✓ ${item.title}: ${item.subtitle}${item.fields?.webConfirmed === 'true' ? ', confirmed on the web' : ', database only'}` : `✗ ${item.title}: ${item.dropReason}`, data: item });
    }
  } catch (e) {
    if (!(e instanceof BudgetExceeded) || !items.some((i) => i.status === 'verified')) throw e;
    partial = true;
    emit(job, { agent: 'cfo', kind: 'money', text: `Budget reached after checking ${items.length} people. Delivering what's verified.` });
  }

  // Web-confirmed people first; database-only ones still make the map, flagged as such.
  const kept = items.filter((i) => i.status === 'verified').sort((a, b) => Number(b.fields?.webConfirmed === 'true') - Number(a.fields?.webConfirmed === 'true')).slice(0, MAX);
  const dropped = items.filter((i) => i.status === 'dropped');
  if (!kept.length) throw new Error(`nobody at ${name} held up: ${dropped.length} people checked`);

  // Writer: why each person matters, and who to approach first. Cites people by key; the audit checks them.
  const ids = Object.fromEntries(kept.map((k, i) => [`P${i + 1}`, `${k.title}, ${k.subtitle}, ${k.fields?.role}${k.fields?.since ? `, in role since ${k.fields.since}` : ''}`]));
  const plan = await step(job, 'writer', 'write', async () => {
    const why = await json<{ people: { id: string; why: string }[] }>({
      model: env.models.fast,
      system: 'For each person, write one plain sentence on why they matter for the client\'s goal, based only on their title and group. No guesses about their opinions.',
      user: `Goal: ${intake.goal} at ${name}\nGroups: ${intake.groups.map((g) => `${g.role}: ${g.why}`).join(' | ')}\nPeople:\n${Object.entries(ids).map(([k, v]) => `${k}: ${v}`).join('\n')}\n\nReturn {"people": [{"id", "why"}]}`,
      check: (v) => (!Array.isArray(v?.people) ? 'people must be an array' : null),
    });
    const order = await writeAudited({
      model: env.models.smart,
      system: 'You plan the approach for a client who wants to reach people at a company. Use ONLY the people given. 3-4 points: who to contact first and why, who to bring in next, who could block it. Each point cites the person ids it relies on. No hedging words ("likely", "may", "might", "could", "probably", "suggests", "seems", "potentially"). Do not add numbers or names that are not in the cited people.',
      user: `Goal: ${intake.goal}\nCompany: ${name}\nPeople:\n${Object.entries(ids).map(([k, v]) => `[${k}] ${v}`).join('\n')}`,
      values: ids,
    });
    return { why: Object.fromEntries(why.people.map((p) => [p.id, p.why])), ...order };
  });
  kept.forEach((k, i) => {
    if (plan.why[`P${i + 1}`]) k.fields = { ...k.fields, why: plan.why[`P${i + 1}`] };
  });

  const webConfirmed = kept.filter((k) => k.fields?.webConfirmed === 'true').length;
  const first = kept[0];
  return {
    headline: `${kept.length} people to talk to at ${name} about ${intake.goal}; start with ${first.title} (${first.subtitle}). ${webConfirmed} of ${kept.length} confirmed on the open web.`,
    company: { name, domain: company.domain },
    goal: intake.goal,
    items: [...kept, ...dropped].map(({ group, ...i }) => i),
    points: plan.points,
    stats: { candidates: pool.length, checked: items.length, verified: kept.length, webConfirmed, dropped: dropped.length, draftRounds: plan.rounds },
    csv: toCsv(['name', 'title', 'role', 'since', 'profile', 'web_confirmed', 'why'], kept.map((k) => [k.title, k.subtitle, k.fields?.role, k.fields?.since, k.link, k.fields?.webConfirmed, k.fields?.why])),
    partial,
  };
}

import { BudgetExceeded, say, step } from '../context.ts';
import { companySearch, directFetch, readPages, usablePage } from '../crust.ts';
import { env } from '../env.ts';
import { json } from '../llm.ts';
import { quoteOnPage, quoteSupports } from '../agents/compare.ts';
import { emit } from '../store.ts';
import type { Check, Deliverable, Item, Job } from '../types.ts';
import { canon, companyRow, looksLikeDomain, money, resolveCompany, RICH_FIELDS, screen, toCsv, writeAudited, type CompanyRow } from './shared.ts';

/**
 * Competitor teardown: who the client competes with and how each one sells itself. Records finds
 * the rivals and their size and funding; Field reads each rival's own site and quotes its
 * positioning, target customer and pricing; the Writer may only cite what passed the quote check.
 */

interface Intake {
  name: string;
  domain: string | null;
  focus: string;
  local: boolean;
}

interface Offer {
  site: boolean;
  url: string;
  pricingUrl: string | null;
  positioning: Claimed | null;
  target: Claimed | null;
  pricing: Claimed | null;
}

interface Claimed {
  value: string;
  quote: string;
  source: string;
  verified: boolean;
  note: string;
}

const WANT = 5;

export async function runCompetitorTeardown(job: Job): Promise<Deliverable> {
  const intake = await step(job, 'lead', 'intake', () =>
    json<Intake>({
      system:
        'You are the Lead at a research agency. A client wants a competitor teardown. Extract the company to tear down against (and its domain if given, else null), what the client cares about most (focus), and whether competitors should come from the same country (local=true only for businesses that compete locally, like banks, payments, retail, services).',
      user: `Client brief: ${job.brief}\nForm fields: ${JSON.stringify(job.input)}\n\nReturn {"name": string, "domain": string|null, "focus": string, "local": boolean}`,
      check: (v) => (!v?.name ? 'missing name' : typeof v.local !== 'boolean' ? 'local must be boolean' : null),
    }),
  );
  if (!job.plan) {
    job.plan = intake;
    say(`Work order: competitor teardown for ${intake.name}, focus: ${intake.focus}`, 'step');
  }

  const company = await step(job, 'lead', 'resolve', () => {
    const raw = String(job.input.company ?? '');
    return resolveCompany(intake.name, intake.domain ?? (looksLikeDomain(raw) ? raw : null), job.brief);
  });
  const name = company.name || intake.name;

  // Field reads the client's own site first: the Writer needs both sides, and the search needs a description.
  const client = await step(job, 'field', 'client', () => readOffer(name, company.domain, intake.focus));

  // Records: companies that describe themselves like the client does.
  const rivals = await step(job, 'records', 'rivals', async () => {
    const about = company.description || client.positioning?.value || name;
    say(`Searching the company database for businesses like ${name}${intake.local && company.country ? ` in ${company.country}` : ''}`, 'tool');
    const r = await companySearch({ query: about.slice(0, 400), mode: 'semantic', country: intake.local && company.country ? company.country : undefined, limit: 25, fields: RICH_FIELDS });
    const brand = name.toLowerCase().split(/\s+/)[0];
    const list = (r.companies ?? []).map(companyRow).filter((c) => c.domain && c.domain !== company.domain && !c.name.toLowerCase().startsWith(brand));
    say(`Records proposed ${list.length} candidates`);
    return list;
  });

  const picked = await step(job, 'lead', 'screen', async () => {
    const kept = await screen(
      `Direct competitors of ${name} (${company.domain}): ${(company.description || client.positioning?.value || '').slice(0, 300)}`,
      rivals,
      undefined,
      `Keep only direct competitors: companies whose product a buyer would weigh against ${name}'s. Best first. Drop the company itself, its subsidiaries, agencies, consultancies, resellers, investors, and companies in a different product category.`,
    );
    return kept.slice(0, WANT + 1);
  });
  if (!picked.length) throw new Error(`no direct competitors of ${name} found in the database`);

  // One step per competitor: a crash or budget stop keeps every teardown already done.
  const items: (Item & { key: string })[] = [];
  let partial = false;
  try {
    for (const c of picked) {
      if (items.filter((i) => i.status === 'verified').length >= WANT) break;
      const item = await step(job, 'field', `teardown:${c.domain}`, async () => toItem(c, await readOffer(c.name, c.domain, intake.focus)), { retries: 1 }).catch((e) => {
        if (e instanceof BudgetExceeded) throw e;
        return { key: c.domain, title: c.name, subtitle: c.domain, link: `https://${c.domain}`, status: 'dropped', checks: [{ name: 'checked', ok: false, note: String(e.message ?? e).slice(0, 120) }], dropReason: 'check failed after retries' } as Item & { key: string };
      });
      items.push(item);
      const ok = item.checks.filter((x) => x.name.endsWith('quoted') && x.ok).length;
      emit(job, { agent: 'verifier', kind: 'check', text: item.status === 'verified' ? `✓ ${item.title}: ${ok} of 3 quotes found on their site` : `✗ ${item.title}: ${item.dropReason}`, data: item });
    }
  } catch (e) {
    if (!(e instanceof BudgetExceeded) || !items.some((i) => i.status === 'verified')) throw e;
    partial = true;
    emit(job, { agent: 'cfo', kind: 'money', text: `Budget reached after ${items.length} competitors. Writing up the ones already verified.` });
  }
  const kept = items.filter((i) => i.status === 'verified');
  if (!kept.length) throw new Error(`no competitor's site could be verified (${items.length} tried)`);

  // Writer: only verified quotes and database numbers are citable.
  const values: Record<string, string> = {};
  const addOffer = (id: string, label: string, o: Offer | null, f?: Record<string, string>) => {
    if (o?.positioning?.verified) values[`${id}.positioning`] = `${label}: ${o.positioning.value} ("${o.positioning.quote}")`;
    if (o?.target?.verified) values[`${id}.target`] = `${label} sells to: ${o.target.value} ("${o.target.quote}")`;
    if (o?.pricing?.verified) values[`${id}.pricing`] = `${label} pricing: ${o.pricing.value} ("${o.pricing.quote}")`;
    for (const k of ['headcount', 'founded', 'funding'] as const) if (f?.[k]) values[`${id}.${k}`] = `${label} ${k}: ${f[k]}`;
  };
  addOffer('C0', name, client, { headcount: company.headcount ? String(company.headcount) : '', founded: company.founded ? String(company.founded) : '', funding: money(company.fundingUsd) });
  kept.forEach((k, i) => addOffer(`C${i + 1}`, k.title, (k as any).offer ?? null, k.fields));

  const brief = await step(job, 'writer', 'write', () =>
    writeAudited({
      model: env.models.smart,
      system:
        'You write a competitor teardown for a client. Use ONLY the facts given; each has a key. Write 4-6 points. Each point starts with "Differs:" (how the client stands apart) or "Exposed:" (where a competitor is stronger or the client is open to attack), states the facts plainly, and ends with one concrete thing the client can do about it. Cite every fact key a point relies on. No hedging words ("likely", "probably", "may", "might", "could", "suggests", "seems", "potentially"). Do not add numbers, names or prices that are not in the cited facts.',
      user: `Client: ${name} (key prefix C0)\nFocus: ${intake.focus}\nFacts:\n${Object.entries(values).map(([k, v]) => `[${k}] ${v}`).join('\n')}`,
      values,
    }),
  );

  const quotes = items.flatMap((i) => i.checks.filter((c) => c.name.endsWith('quoted') && !/no pricing/.test(c.note)));
  return {
    headline: `${name} competes most directly with ${kept.map((k) => k.title).join(', ')}. ${brief.points.length} points on where it differs and where it is exposed, each backed by a quote from the competitor's own site or the company database.`,
    company: { name, domain: company.domain },
    focus: intake.focus,
    client: { positioning: client.positioning, target: client.target, pricing: client.pricing, url: client.url },
    items: [...kept, ...items.filter((i) => i.status === 'dropped')].map(({ key, ...i }) => {
      const { offer, ...rest } = i as any;
      return rest as Item;
    }),
    points: brief.points,
    stats: { candidates: rivals.length, competitors: kept.length, checked: items.length, dropped: items.length - kept.length, quotesChecked: quotes.length, quotesVerified: quotes.filter((q) => q.ok).length, draftRounds: brief.rounds },
    csv: toCsv(['competitor', 'domain', 'positioning', 'target', 'pricing', 'headcount', 'founded', 'funding'], kept.map((k) => [k.title, k.subtitle, k.fields?.positioning, k.fields?.target, k.fields?.pricing, k.fields?.headcount, k.fields?.founded, k.fields?.funding])),
    partial,
  };
}

/** Field: read a company's homepage (and its pricing page, if it has one) and quote how it sells itself. */
async function readOffer(name: string, domain: string, focus: string): Promise<Offer> {
  say(`Reading ${domain}`, 'tool');
  const home = `https://${domain}`;
  const [site] = await readPages([home], { humanRetry: true });
  if (!site?.ok) return { site: false, url: home, pricingUrl: null, positioning: null, target: null, pricing: null };
  // A pricing page is worth a free fetch, never a paid one: plenty of companies don't have one.
  const p = await directFetch(`${home}/pricing`);
  const pricingPage = usablePage(p) && canon(p.url) !== canon(site.url) ? p : null;
  const pages: Record<string, { url: string; text: string }> = { H: { url: site.url, text: site.text } };
  if (pricingPage) pages.P = { url: pricingPage.url, text: pricingPage.text };

  const out = await json<{ positioning: Raw | null; target: Raw | null; pricing: Raw | null }>({
    system:
      "You read a company's own web pages and pull out how it sells itself. For each item give a short plain value and a quote copied character-for-character from the page (max 200 chars) that states it, plus the page id. positioning: what the product is, in one line. target: who it is for (type of customer or team). pricing: the plan prices or pricing model if the pages state them, else null. Use null for anything the pages don't state. Never use outside knowledge.",
    user: `Company: ${name} (${domain})\nClient focus: ${focus}\n\n${Object.entries(pages).map(([id, pg]) => `[${id}] ${pg.url}\n${pg.text.slice(0, id === 'H' ? 6000 : 5000)}`).join('\n\n')}\n\nReturn {"positioning": {"value", "quote", "page"}|null, "target": {"value", "quote", "page"}|null, "pricing": {"value", "quote", "page"}|null}`,
    check: (v) => (!v || typeof v !== 'object' || !('positioning' in v) ? 'positioning key required' : null),
  });

  // Verifier: a quote counts only if it is on the page it names (and, for prices, says the number).
  const verify = (r: Raw | null, isPrice = false): Claimed | null => {
    if (!r?.value || !r.quote) return null;
    const page = pages[r.page] ?? pages.H;
    const onPage = quoteOnPage(r.quote, page.text);
    const says = !isPrice || !/\d/.test(r.value) || quoteSupports('money', r.value, r.quote);
    return { value: String(r.value).slice(0, 200), quote: r.quote.slice(0, 240), source: page.url, verified: onPage && says, note: !onPage ? 'quote not found on the page' : !says ? "quote doesn't state the price" : 'quote found on the page' };
  };
  return { site: true, url: site.url, pricingUrl: pricingPage?.url ?? null, positioning: verify(out.positioning), target: verify(out.target), pricing: verify(out.pricing, true) };
}

interface Raw {
  value: string;
  quote: string;
  page: string;
}

function toItem(c: CompanyRow & { why?: string }, o: Offer): Item & { key: string; offer: Offer } {
  const checks: Check[] = [
    { name: 'company record', ok: c.headcount != null || c.founded != null, note: [c.headcount != null && `${c.headcount} staff`, c.founded && `founded ${c.founded}`, c.fundingUsd && `${money(c.fundingUsd)} raised`].filter(Boolean).join(', ') || 'thin database record', source: 'crustdata' },
    { name: 'site loads', ok: o.site, note: o.site ? o.url : 'could not load the homepage', source: o.url },
  ];
  const q = (label: string, x: Claimed | null, missing: string) => checks.push({ name: `${label} quoted`, ok: !!x?.verified, note: x ? (x.verified ? `"${x.quote}"` : `${x.note}: "${x.quote.slice(0, 100)}"`) : missing, source: x?.source });
  q('positioning', o.positioning, 'no positioning line found');
  q('target customer', o.target, 'the site does not say who it is for');
  q('pricing', o.pricing, o.pricingUrl ? 'no prices on the pricing page' : 'no pricing published');
  const ok = o.site && !!o.positioning?.verified;
  const v = (x: Claimed | null) => (x?.verified ? x.value : '');
  return {
    key: c.domain,
    title: c.name,
    subtitle: c.domain,
    link: o.url,
    status: ok ? 'verified' : 'dropped',
    dropReason: ok ? undefined : !o.site ? 'website did not load' : 'positioning quote not found on their site',
    checks,
    fields: {
      positioning: v(o.positioning),
      target: v(o.target),
      pricing: v(o.pricing),
      headcount: c.headcount != null ? String(c.headcount) : '',
      founded: c.founded ? String(c.founded) : '',
      funding: money(c.fundingUsd),
      lastRound: c.lastRound ?? '',
      hq: c.hq ?? c.country ?? '',
      why: c.why ?? '',
    },
    offer: o,
  };
}

import { BudgetExceeded, say, step } from '../context.ts';
import { companySearch, readPages } from '../crust.ts';
import { json } from '../llm.ts';
import { quoteOnPage } from '../agents/compare.ts';
import { emit } from '../store.ts';
import type { Check, Deliverable, Item, Job } from '../types.ts';
import { companyRow, money, RICH_FIELDS, screen, toCsv, type CompanyRow } from './shared.ts';

/**
 * Market map: the companies in a space, with size, age and funding from the database, each one
 * confirmed on its own homepage with a quoted line that shows what it does.
 */

interface Intake {
  space: string;
  country: string | null;
  count: number;
  exclude: string[];
  headcountMin: number | null;
  headcountMax: number | null;
}

export async function runMarketMap(job: Job): Promise<Deliverable> {
  const intake = await step(job, 'lead', 'intake', () =>
    json<Intake>({
      system:
        "You are the Lead at a research agency. Turn a client's market-map request into a work order: a one-line description of the companies in the space (for a semantic company search), a country filter if the client named one (full English name like \"United States\", else null), how many companies, any company domains to exclude, and an employee-count range if the client gave one (else null).",
      user: `Client brief: ${job.brief}\nForm fields: ${JSON.stringify(job.input)}\n\nReturn {"space": string, "country": string|null, "count": number, "exclude": string[], "headcountMin": number|null, "headcountMax": number|null}`,
      check: (v) => (!v?.space ? 'space required' : null),
    }),
  );
  const want = Math.max(1, Math.min(25, Number(job.input.count ?? intake.count ?? 10)));
  const country = intake.country ?? (job.input.country ? String(job.input.country) : null);
  if (!job.plan) {
    job.plan = { ...intake, country, count: want };
    say(`Work order: map ${want} companies in ${intake.space}${country ? ` (${country})` : ''}`, 'step');
  }

  const items: Item[] = [];
  const seen = new Set((intake.exclude ?? []).map((d) => d.toLowerCase()));
  const verifiedCount = () => items.filter((i) => i.status === 'verified').length;
  let cursor: string | null | undefined;
  let partial = false;

  try {
    for (let page = 1; page <= 4 && verifiedCount() < want; page++) {
      const batch = await step(job, 'records', `source:${page}`, async () => {
        say(`Searching the company database (page ${page})`, 'tool');
        const r = await companySearch({ query: intake.space, country: country ?? undefined, minStaff: intake.headcountMin, maxStaff: intake.headcountMax, limit: Math.min(40, want * 3 + 6), cursor: cursor ?? undefined, fields: RICH_FIELDS });
        return { next: r.next_cursor, companies: (r.companies ?? []).map(companyRow) };
      });
      cursor = batch.next;
      const fresh = batch.companies.filter((c) => c.domain && !seen.has(c.domain));
      fresh.forEach((c) => seen.add(c.domain));
      if (!fresh.length && !cursor) break;

      const screened = await step(job, 'lead', `screen:${page}`, () =>
        screen(
          `Companies in this space: ${intake.space}`,
          fresh,
          { min: intake.headcountMin, max: intake.headcountMax },
          "Keep only companies whose own product is in this space, best known first. Drop agencies, consultancies, investors, media, directories, and companies that only use or resell such products.",
        ),
      );

      for (let i = 0; i < screened.length; i += 3) {
        if (verifiedCount() >= want) break;
        const group = screened.slice(i, i + Math.min(3, want - verifiedCount()));
        const done = await Promise.all(
          group.map((c) =>
            step(job, 'field', `check:${c.domain}`, () => checkCompany(intake.space, c), { retries: 1 }).catch((e) => {
              if (e instanceof BudgetExceeded) throw e;
              return { title: c.name, subtitle: c.domain, link: `https://${c.domain}`, status: 'dropped', checks: [{ name: 'checked', ok: false, note: String(e.message ?? e).slice(0, 120) }], dropReason: 'check failed after retries' } as Item;
            }),
          ),
        );
        for (const it of done) {
          items.push(it);
          emit(job, { agent: 'verifier', kind: 'check', text: it.status === 'verified' ? `✓ ${it.title}: "${(it.fields?.quote ?? '').slice(0, 90)}"` : `✗ ${it.title}: ${it.dropReason}`, data: it });
        }
      }
      if (!cursor) break;
    }
  } catch (e) {
    if (!(e instanceof BudgetExceeded)) throw e;
    if (!verifiedCount()) throw e;
    partial = true;
    emit(job, { agent: 'cfo', kind: 'money', text: `Budget reached with ${verifiedCount()} of ${want} companies verified. Delivering those and charging only for them.` });
  }

  const verified = items.filter((i) => i.status === 'verified').slice(0, want);
  const dropped = items.filter((i) => i.status === 'dropped');
  if (!verified.length) throw new Error(`no companies survived verification (${dropped.length} checked)`);
  if (verified.length < want && !partial) say(`Ran out of matching companies: ${verified.length} of ${want} verified`, 'step');

  const price = job.quote ? Math.max(0.5, Math.round(((job.quote.priceUsd * Math.min(verified.length, want)) / want) * 2) / 2) : 0;
  const funded = verified.filter((v) => v.fields?.funding).length;
  return {
    headline: `${verified.length} of ${want} companies mapped in ${intake.space}${country ? ` (${country})` : ''}, each confirmed on its own website${funded ? `; ${funded} with disclosed funding` : ''}.`,
    space: intake.space,
    items: [...verified, ...dropped],
    stats: { wanted: want, verified: verified.length, checked: items.length, dropped: dropped.length, withFunding: funded },
    csv: toCsv(['company', 'domain', 'what_they_do', 'headcount', 'founded', 'funding_usd', 'last_round', 'hq'], verified.map((v) => [v.title, v.subtitle, v.fields?.quote, v.fields?.headcount, v.fields?.founded, v.fields?.fundingUsd, v.fields?.lastRound, v.fields?.hq])),
    partial: verified.length < want,
    priceUsd: price,
  };
}

/** Field: read the homepage and quote the line that shows the company is in the space. */
async function checkCompany(space: string, c: CompanyRow & { why: string }): Promise<Item> {
  const checks: Check[] = [];
  const fields: Record<string, string> = {
    headcount: c.headcount != null ? String(c.headcount) : '',
    founded: c.founded ? String(c.founded) : '',
    funding: money(c.fundingUsd),
    fundingUsd: c.fundingUsd != null ? String(c.fundingUsd) : '',
    lastRound: c.lastRound ?? '',
    hq: c.hq ?? c.country ?? '',
  };
  const item = (status: Item['status'], dropReason?: string): Item => ({ title: c.name, subtitle: c.domain, link: `https://${c.domain}`, status, checks, fields, dropReason });
  checks.push({ name: 'company record', ok: c.headcount != null || c.founded != null, note: [c.headcount != null && `${c.headcount} staff`, c.founded && `founded ${c.founded}`, c.hq].filter(Boolean).join(', ') || 'thin database record', source: 'crustdata' });

  say(`Reading ${c.domain}`, 'tool');
  const [site] = await readPages([`https://${c.domain}`], { humanRetry: true });
  checks.push({ name: 'site is live', ok: !!site?.ok, note: site?.ok ? site.title.slice(0, 80) : 'could not load the homepage', source: `https://${c.domain}` });
  if (!site?.ok) return item('dropped', 'website did not load');

  // The site must be the company the database means: its name shows up on its own homepage.
  const brand = c.name.toLowerCase().replace(/[^a-z0-9 ]/g, ' ').split(/\s+/).filter((w) => w.length > 2 && !/^(inc|ltd|llc|the|technologies|labs|corp)$/.test(w))[0] ?? c.name.toLowerCase();
  const named = `${site.title} ${site.text.slice(0, 20_000)}`.toLowerCase().includes(brand);
  checks.push({ name: 'site names the company', ok: named, note: named ? `"${brand}" appears on the homepage` : `"${brand}" not on the homepage; the domain may belong to someone else`, source: site.url });
  if (!named) return item('dropped', 'homepage does not name the company');

  const r = await json<{ inSpace: boolean; quote: string; what: string }>({
    system: "You check whether a company's product is in a given market space, using ONLY its homepage text. Quote the exact words from the page that show what it does (max 160 chars), and say what it does in under 12 words. If the page doesn't show it is in the space, inSpace=false.",
    user: `Space: ${space}\nCompany: ${c.name} (${c.domain})\nHomepage text:\n${site.text.slice(0, 5000)}\n\nReturn {"inSpace": boolean, "quote": string, "what": string}`,
    check: (v) => (typeof v?.inSpace !== 'boolean' ? 'inSpace must be boolean' : null),
  });
  const quoted = r.inSpace && quoteOnPage(r.quote, site.text);
  checks.push({ name: 'in the space', ok: quoted, note: quoted ? `"${r.quote}"` : r.inSpace ? 'claimed, but the quote is not on the page' : r.what, source: site.url });
  if (!quoted) return item('dropped', r.inSpace ? 'quote not found on their site' : `not in the space: ${r.what}`);
  fields.what = r.what;
  fields.quote = r.quote;
  const out = item('verified');
  out.subtitle = `${c.domain} · ${r.what}`;
  return out;
}

import { BudgetExceeded, say, step } from '../context.ts';
import { companyEnrich, companySearch, peopleAt, readPages, webSearch, type WebResult } from '../crust.ts';
import { json } from '../llm.ts';
import { quoteOnPage } from '../agents/compare.ts';
import type { Check, Deliverable, Item, Job, Verdict } from '../types.ts';
import { clean, companyRow, dedupe, dnsState, looksLikeDomain, money, personOf, personOnWeb, RICH_FIELDS, seniority, type CompanyRow } from './shared.ts';

/**
 * Vendor check: "check before you pay". Every signal is a plain check with a severity, and the
 * verdict is computed from the checks in code. The model only reads web snippets and must quote them.
 */

interface Intake {
  name: string;
  domain: string | null;
  context: string;
}

interface Mention {
  url: string;
  title: string;
  snippet: string;
  from: 'search' | 'news';
  about: boolean;
  kind: 'scam' | 'complaint' | 'lawsuit' | 'distress' | 'neutral' | 'positive';
  quote: string;
  quoted: boolean;
}

const YEAR = new Date().getFullYear();

export async function runVendorCheck(job: Job): Promise<Deliverable> {
  const raw = String(job.input.company ?? '');
  const intake = await step(job, 'lead', 'intake', () =>
    json<Intake>({
      system: 'You are the Lead at a research agency. A client is about to pay a supplier and wants it checked. Extract the company name, its website domain if the client gave one (else null), and the deal context in one line.',
      user: `Client brief: ${job.brief}\nForm fields: ${JSON.stringify(job.input)}\n\nReturn {"name": string, "domain": string|null, "context": string}`,
      check: (v) => (!v?.name ? 'missing name' : null),
    }),
  );
  const givenDomain = clean(intake.domain) ?? (looksLikeDomain(raw) ? clean(raw) : null);
  if (!job.plan) {
    job.plan = { ...intake, domain: givenDomain };
    say(`Work order: check ${intake.name}${givenDomain ? ` (${givenDomain})` : ''} before paying: ${intake.context}`, 'step');
  }

  // 1. Records: is there a company record, and is it this company?
  const rec = await step(job, 'records', 'record', async () => {
    let row: CompanyRow | null = null;
    if (givenDomain) {
      say(`Looking up ${givenDomain} in the company database`, 'tool');
      const c = await companyEnrich(givenDomain).catch((e) => {
        if (e instanceof BudgetExceeded) throw e;
        return null;
      });
      if (c) row = companyRow(c);
    }
    if (!row) {
      say(`Searching the company database for "${intake.name}"`, 'tool');
      const r = await companySearch({ query: givenDomain ? `${intake.name} ${givenDomain}` : intake.name, limit: 5, fields: RICH_FIELDS });
      const list = (r.companies ?? []).map(companyRow);
      row = (givenDomain ? list.find((c) => c.domain === givenDomain) : list.filter((c) => norm(c.name) === norm(intake.name)).sort((a, b) => (b.headcount ?? 0) - (a.headcount ?? 0))[0]) ?? null;
    }
    say(row ? `Found a record: ${row.name} (${row.domain}), ${row.headcount ?? '?'} staff, founded ${row.founded ?? '?'}` : 'No company record matches');
    return row;
  });
  const name = rec?.name || intake.name;
  let domain = givenDomain ?? rec?.domain ?? null;

  // 2. Field: does the domain exist and does the site say it's this company?
  const site = await step(job, 'field', 'site', async () => {
    let d = domain;
    if (!d) {
      say(`No domain given or on record; searching for ${name}'s website`, 'tool');
      const hits = await webSearch(`${name} official website`).catch(() => [] as WebResult[]);
      const brand = norm(name).split(' ')[0];
      d = clean(hits.find((h) => clean(h.url)?.includes(brand))?.url) ?? null;
    }
    if (!d) return { domain: null, dns: 'none' as const, ok: false, title: '', named: false, url: '' };
    const dns = await dnsState(d);
    if (dns === 'none') return { domain: d, dns, ok: false, title: '', named: false, url: `https://${d}` };
    say(`Reading ${d}`, 'tool');
    const [p] = await readPages([`https://${d}`], { humanRetry: true });
    const brand = norm(name).split(' ').find((w) => w.length > 2) ?? norm(name);
    return { domain: d, dns, ok: !!p?.ok, title: p?.title ?? '', named: !!p?.ok && norm(`${p.title} ${p.text.slice(0, 20_000)}`).includes(brand), url: p?.url ?? `https://${d}` };
  });
  domain = site.domain;

  // 3. Records then Field: a named leader in the people database, and the same person on the web.
  const leader = await step(job, 'records', 'leader', async () => {
    if (!domain) return null;
    say(`Looking up who runs ${name}`, 'tool');
    const r = await peopleAt({ domain, titles: ['CEO', 'Founder', 'Managing Director', 'Owner', 'President', 'Chief Executive'], limit: 5 }).catch((e) => {
      if (e instanceof BudgetExceeded) throw e;
      return { profiles: [] };
    });
    const people = (r.profiles ?? []).map(personOf).filter((p) => p.name).sort((a, b) => seniority(a.title, a.seniority) - seniority(b.title, b.seniority));
    return people[0] ?? null;
  });
  const leaderWeb = await step(job, 'field', 'leader-web', async () => {
    if (!leader) return null;
    say(`Checking ${leader.name} on the open web`, 'tool');
    const w = await personOnWeb(leader.name, name);
    return { mentions: w.mentions.length, left: w.left ? w.left.snippet.slice(0, 160) : null, url: (w.left ?? w.mentions[0])?.url ?? null };
  });

  // 4. Field: complaints, scam reports, lawsuits and news. The model sorts snippets; each must be quoted.
  const mentions = await step(job, 'field', 'mentions', async () => {
    const q = `"${name}"${domain ? ` OR ${domain}` : ''} scam OR fraud OR complaint OR lawsuit`;
    say(`Searching the web: ${q}`, 'tool');
    const bad = await webSearch(q).catch((e) => (e instanceof BudgetExceeded ? Promise.reject(e) : [] as WebResult[]));
    say(`Searching the news for ${name}`, 'tool');
    const news = await webSearch(`${name}${domain ? ` ${domain}` : ''}`, ['news']).catch((e) => (e instanceof BudgetExceeded ? Promise.reject(e) : [] as WebResult[]));
    const all = [...dedupe(bad).map((r) => ({ ...r, from: 'search' as const })), ...dedupe(news).filter((n) => !bad.some((b) => b.url === n.url)).map((r) => ({ ...r, from: 'news' as const }))].slice(0, 14);
    if (!all.length) return [] as Mention[];
    const r = await json<{ items: { i: number; about: boolean; kind: Mention['kind']; quote: string }[] }>({
      system:
        `You sort web search snippets for a supplier check. For each snippet decide: about=true only if it is about THIS company (same name AND same business; not a namesake, not a generic article). kind: "scam" if it says this company itself is a scam or defrauded customers; "complaint" for a customer complaint about its service; "lawsuit" for a lawsuit, regulator action, fine or ban against it; "distress" for shutdown, insolvency, layoffs or unpaid debts; "neutral" for anything else (including articles about fraud prevention or fraud by third parties on its platform); "positive" for awards, funding, partnerships. quote: the words from the snippet that show it, copied exactly (max 160 chars).`,
      user: `Company: ${name}${domain ? ` (${domain})` : ''}${rec?.description ? `, ${rec.description.slice(0, 200)}` : ''}\n\nSnippets:\n${all.map((s, i) => `${i}. ${s.title}. ${s.snippet}\n   ${s.url}`).join('\n')}\n\nReturn {"items": [{"i", "about", "kind", "quote"}]} with one entry per snippet.`,
      check: (v) => (!Array.isArray(v?.items) ? 'items must be an array' : v.items.some((x: any) => !['scam', 'complaint', 'lawsuit', 'distress', 'neutral', 'positive'].includes(x.kind)) ? 'kind must be scam, complaint, lawsuit, distress, neutral or positive' : null),
    });
    return r.items
      .filter((x) => all[x.i])
      .map((x) => {
        const s = all[x.i];
        return { url: s.url, title: s.title, snippet: s.snippet, from: s.from, about: !!x.about, kind: x.kind, quote: x.quote ?? '', quoted: !!x.quote && quoteOnPage(x.quote, `${s.title}. ${s.snippet}`) } as Mention;
      });
  });

  // 5. Verifier: every signal as a plain check; the verdict is arithmetic on the failures.
  const result = await step(job, 'verifier', 'verdict', async () => {
    const checks: Check[] = [];
    const add = (c: Check) => checks.push(c);
    const established = !!rec && (rec.headcount ?? 0) >= 200 && !!rec.founded && YEAR - rec.founded >= 5;
    const soften = (s: Check['severity']): Check['severity'] => (established ? (s === 'high' ? 'medium' : 'low') : s);

    add(site.domain
      ? { name: 'domain resolves', ok: site.dns !== 'none', severity: site.dns === 'unknown' ? 'low' : 'high', note: site.dns === 'ok' ? `${site.domain} resolves` : site.dns === 'unknown' ? 'DNS lookup timed out' : `${site.domain} does not exist in DNS`, source: 'dns' }
      : { name: 'domain resolves', ok: false, severity: 'medium', note: 'no website given, on record, or found on the web', source: 'web search' });
    if (site.dns !== 'none' && site.domain) {
      add({ name: 'website loads', ok: site.ok, severity: 'medium', note: site.ok ? site.title.slice(0, 90) || site.url : 'the homepage did not load', source: site.url });
      if (site.ok) add({ name: 'website names the company', ok: site.named, severity: 'medium', note: site.named ? `${name} appears on its own homepage` : `the homepage does not mention ${name}`, source: site.url });
    }
    add({ name: 'company record', ok: !!rec, severity: 'medium', note: rec ? `${rec.name} (${rec.domain})` : 'no record in the company database', source: 'crustdata' });
    if (rec && givenDomain) {
      const matches = rec.domain === givenDomain && sameName(rec.name, intake.name);
      add({ name: 'record matches the name and domain', ok: matches, severity: 'high', note: matches ? `${rec.name} is registered at ${rec.domain}` : `the record for ${givenDomain} is "${rec.name}" (${rec.domain}), not "${intake.name}"`, source: 'crustdata' });
    }
    if (rec) {
      const age = rec.founded ? YEAR - rec.founded : null;
      add({
        name: 'founded year plausible',
        ok: age != null && age >= 2 && age < 200,
        severity: age == null ? 'low' : age < 0 ? 'high' : age < 1 ? 'medium' : 'low',
        note: age == null ? 'no founding year on record' : age < 0 ? `founding year ${rec.founded} is in the future` : age < 2 ? `founded ${rec.founded}: under two years old` : `founded ${rec.founded}`,
        source: 'crustdata',
      });
      add({ name: 'headcount plausible', ok: (rec.headcount ?? 0) >= 5, severity: 'low', note: rec.headcount == null ? 'no headcount on record' : `${rec.headcount} staff on record`, source: 'crustdata' });
    }
    add({ name: 'named leader in the people database', ok: !!leader, severity: 'medium', note: leader ? `${leader.name}, ${leader.title}` : 'no CEO, founder or owner on record', source: leader?.profileUrl ?? 'crustdata' });
    if (leader) {
      const ok = !!leaderWeb && leaderWeb.mentions > 0 && !leaderWeb.left;
      add({ name: 'leader confirmed on the web', ok, severity: 'medium', note: leaderWeb?.left ? `web says they left: "${leaderWeb.left}"` : ok ? `${leaderWeb!.mentions} page${leaderWeb!.mentions > 1 ? 's' : ''} link ${leader.name} to ${name}` : `no web page links ${leader.name} to ${name}`, source: leaderWeb?.url ?? undefined });
    }

    const hits = (k: Mention['kind']) => mentions.filter((m) => m.about && m.quoted && m.kind === k);
    const scams = hits('scam'), suits = hits('lawsuit'), complaints = hits('complaint'), distress = hits('distress');
    const ev = (ms: Mention[]) => (ms.length ? `: "${ms[0].quote}"` : '');
    add({ name: 'no scam or fraud reports', ok: !scams.length, severity: soften(scams.length >= 2 ? 'high' : 'medium'), note: scams.length ? `${scams.length} report${scams.length > 1 ? 's' : ''} call it a scam or fraud${ev(scams)}` : 'none found', source: scams[0]?.url });
    add({ name: 'no lawsuits or regulator action', ok: !suits.length, severity: soften('medium'), note: suits.length ? `${suits.length} mention${suits.length > 1 ? 's' : ''}${ev(suits)}` : 'none found', source: suits[0]?.url });
    add({ name: 'no pattern of complaints', ok: complaints.length < 3, severity: soften(complaints.length >= 3 ? 'medium' : 'low'), note: complaints.length ? `${complaints.length} complaint${complaints.length > 1 ? 's' : ''}${ev(complaints)}` : 'none found', source: complaints[0]?.url });
    add({ name: 'no signs of distress', ok: !distress.length, severity: soften('medium'), note: distress.length ? `${distress.length} mention${distress.length > 1 ? 's' : ''} of shutdown, layoffs or debts${ev(distress)}` : 'none found', source: distress[0]?.url });
    const news = mentions.filter((m) => m.about && m.from === 'news');
    add({ name: 'covered in the news', ok: news.length > 0, severity: 'low', note: news.length ? `${news.length} news item${news.length > 1 ? 's' : ''}, e.g. "${news[0].title.slice(0, 90)}"` : 'no news coverage found', source: news[0]?.url });

    const fails = (s: Check['severity']) => checks.filter((c) => !c.ok && c.severity === s).length;
    const high = fails('high'), medium = fails('medium'), low = fails('low');
    const verdict: Verdict = high ? 'red' : medium >= 2 || (medium >= 1 && low >= 2) ? 'amber' : 'green';
    say(`${checks.filter((c) => c.ok).length} of ${checks.length} checks passed; ${high} serious, ${medium} medium, ${low} minor problems → ${verdict}`, 'check');
    return { checks, verdict, high, medium, low };
  });

  const { checks, verdict } = result;
  const failed = checks.filter((c) => !c.ok && c.severity !== 'low');
  const lead = { green: 'Green: no serious problems found', amber: 'Amber: verify before you pay', red: 'Red: do not pay until this is explained' }[verdict as 'green' | 'amber' | 'red'];
  const items: Item[] = [
    {
      title: name,
      subtitle: domain ?? 'no website found',
      link: domain ? `https://${domain}` : undefined,
      status: verdict === 'red' ? 'dropped' : 'verified',
      dropReason: verdict === 'red' ? failed.filter((c) => c.severity === 'high').map((c) => c.note).join('; ') : undefined,
      checks,
      fields: { founded: rec?.founded ? String(rec.founded) : '', headcount: rec?.headcount != null ? String(rec.headcount) : '', hq: rec?.hq ?? rec?.country ?? '', funding: money(rec?.fundingUsd), leader: leader ? `${leader.name}, ${leader.title}` : '' },
    },
    // The evidence the model sorted: kept when it's about this company and its quote is in the snippet.
    ...mentions
      .filter((m) => m.kind !== 'neutral' || m.from === 'news')
      .map((m) => ({
        title: m.title.slice(0, 140),
        subtitle: m.quote || m.snippet.slice(0, 160),
        link: m.url,
        status: m.about && m.quoted ? 'verified' : 'dropped',
        dropReason: !m.about ? 'about a different company or not about it at all' : !m.quoted ? 'quote not found in the snippet' : undefined,
        checks: [
          { name: 'about this company', ok: m.about, note: m.about ? `about ${name}` : 'not about this company' },
          { name: 'quote in the snippet', ok: m.quoted, note: m.quoted ? 'found word for word' : 'not found' },
        ],
        fields: { kind: m.kind, from: m.from },
      }) as Item),
  ];
  return {
    headline: `${lead} for ${name}${domain ? ` (${domain})` : ''}. ${checks.filter((c) => c.ok).length} of ${checks.length} checks passed${failed.length ? `; problems: ${failed.map((c) => c.name).join(', ')}` : ''}.`,
    verdict,
    company: { name, domain },
    context: intake.context,
    items,
    stats: { checks: checks.length, passed: checks.filter((c) => c.ok).length, high: result.high, medium: result.medium, low: result.low, mentions: mentions.length, mentionsAbout: mentions.filter((m) => m.about && m.quoted).length },
  };
}

const norm = (s: string) => s.toLowerCase().normalize('NFKD').replace(/[^\p{L}\p{N} ]/gu, ' ').replace(/\b(inc|ltd|llc|limited|plc|gmbh|corp|corporation|co|company|technologies|the)\b/g, ' ').replace(/\s+/g, ' ').trim();

/** "Paystack" and "Paystack Payments Limited" are the same name; "Acme" and "Globex" aren't. */
function sameName(a: string, b: string) {
  const x = norm(a), y = norm(b);
  if (!x || !y) return false;
  if (looksLikeDomain(b)) return y.replace(/ .*/, '').startsWith(x.split(' ')[0]) || x.replace(/ /g, '').includes(norm(b.split('.')[0]).replace(/ /g, ''));
  return x === y || x.startsWith(y) || y.startsWith(x) || x.split(' ')[0] === y.split(' ')[0];
}

